6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":1218,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 3.38\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T72a,"])self.__next_f.push([1,"There are three degrees of covering of the living entity by which his pure consciousness is obscured. This covering is but lust under different manifestations like smoke in the fire, dust on the mirror, and the womb about the embryo. When lust is compared to smoke, it is understood that the fire of the living spark can be a little perceived. In other words, when the living entity exhibits his Kṛṣṇa consciousness slightly, he may be likened to the fire covered by smoke. Although fire is necessary where there is smoke, there is no overt manifestation of fire in the early stage. This stage is like the beginning of Kṛṣṇa consciousness. The dust on the mirror refers to a cleansing process of the mirror of the mind by so many spiritual methods. The best process is to chant the holy names of the Lord. The embryo covered by the womb is an analogy illustrating a helpless position, for the child in the womb is so helpless that he cannot even move. This stage of living condition can be compared to that of the trees. The trees are also living entities, but they have been put in such a condition of life by such a great exhibition of lust that they are almost void of all consciousness. The covered mirror is compared to the birds and beasts, and the smoke-covered fire is compared to the human being. In the form of a human being, the living entity may revive a little Kṛṣṇa consciousness, and, if he makes further development, the fire of spiritual life can be kindled in the human form of life. By careful handling of the smoke in the fire, fire can be made to blaze. Therefore the human form of life is a chance for the living entity to escape the entanglement of material existence. In the human form of life, one can conquer the enemy, lust, by cultivation of Kṛṣṇa consciousness under able guidance."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":1218,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"38\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 38\",\"advanced_view_url_path\":\"/en/library/bg/3/advanced-view/#bb1083\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/3/38/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/3/38/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\