e\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-nitya\",{\"href\":\"/en/search/synonyms/?original=nitya\",\"children\":[\"$\",\"em\",null,{\"children\":\"nitya\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-vairiṇā\",{\"href\":\"/en/search/synonyms/?original=vairiṇā\",\"children\":[\"$\",\"em\",null,{\"children\":\"vairiṇā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"by the eternal enemy\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-5\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-kāma\",{\"href\":\"/en/search/synonyms/?original=kāma\",\"children\":[\"$\",\"em\",null,{\"children\":\"kāma\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-rūpeṇa\",{\"href\":\"/en/search/synonyms/?original=rūpeṇa\",\"children\":[\"$\",\"em\",null,{\"children\":\"rūpeṇa\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"in the form of lust\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-6\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-kaunteya\",{\"href\":\"/en/search/synonyms/?original=kaunteya\",\"children\":[\"$\",\"em\",null,{\"children\":\"kaunteya\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"O son of Kuntī\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-7\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-duṣpūreṇa\",{\"href\":\"/en/search/synonyms/?original=duṣpūreṇa\",\"children\":[\"$\",\"em\",null,{\"children\":\"duṣpūreṇa\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"never to be satisfied\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-8\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-analena\",{\"href\":\"/en/search/synonyms/?original=analena\",\"children\":[\"$\",\"em\",null,{\"children\":\"analena\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":